import type { dynamicObj } from 'src/pages/assets';

// Builds a builder route for the given base path, carrying layout_type in the
// path and layout_template_id / sub_doc_type_key as query params.
function buildRoute(basePath: string, params: dynamicObj) {
  let navigateTo = '';
  try {
    navigateTo = basePath + params.doc_type_key;

    if (params.layout_type) {
      navigateTo += '/' + params.layout_type;
    }

    const queryParts: string[] = [];
    if (params.layout_template_id) {
      queryParts.push('id=' + encodeURIComponent(params.layout_template_id));
    }
    if (params.sub_doc_type_key) {
      queryParts.push('sub_doc_type=' + encodeURIComponent(params.sub_doc_type_key));
    }
    if (queryParts.length > 0) {
      navigateTo += '?' + queryParts.join('&');
    }
  } catch (err) {
    logError(err);
  }
  return navigateTo;
}

export const formBuilderRouter = {
  // Legacy layout builder route. Still used by callers across the app.
  getDetailViewRoute(params: dynamicObj) {
    return buildRoute('/layout-builder/', params);
  },

  // New form builder route (opens the same builder for now — migration in progress).
  getFormBuilderRoute(params: dynamicObj) {
    return buildRoute('/layouts/form-builder/', params);
  },
};
